"use client";

import { useId, useRef, useState } from "react";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  type AlertDialogMotion,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  type ConfirmActionCopy,
  confirmView,
  nextShown,
  shouldClose,
} from "@/components/ui/confirm-action-dialog-model";
import { FormError } from "@/components/ui/form-error";

/**
 * `use<Feature>Actions()` 的返回值。hook 是业务代码，写在业务目录。
 * `open(kind)` 时清掉上一次的 `error`；`kind` 为 null 表示对话框关闭。
 */
type ConfirmActions<Kind extends string> = {
  open: (kind: Kind) => void;
  confirm: () => void;
  closeConfirm: () => void;
  error: string | null;
  isPending: boolean;
  kind: Kind | null;
};

/** 确认框的动效预设，透传给 `AlertDialog`（ADR 0021）。缺省 `pop`。 */
type ConfirmActionDialogMotion = AlertDialogMotion;

/** 不可撤销动作的确认框。标题是「{action}「{target}」？」，失败显示在页脚按钮上方。 */
function ConfirmActionDialog<Kind extends string>({
  actions,
  copy,
  target,
  motion,
}: {
  actions: ConfirmActions<Kind>;
  copy: Record<Kind, ConfirmActionCopy>;
  target: string;
  /** 动效预设，不写就用 `AlertDialog` 的缺省 `pop`。 */
  motion?: ConfirmActionDialogMotion;
}) {
  const { kind, isPending, error, confirm, closeConfirm } = actions;
  const cancelRef = useRef<HTMLButtonElement>(null);
  const labelId = useId();

  // 关闭动画期间 kind 已是 null，继续显示上一次的文案。
  const [shown, setShown] = useState(() => nextShown<Kind>(null, kind, target));
  const next = nextShown(shown, kind, target);
  if (next !== shown) setShown(next);

  const view = next === null ? null : confirmView(copy[next.kind], next.target, isPending);

  return (
    <AlertDialog
      motion={motion}
      open={kind !== null}
      onOpenChange={(open) => {
        if (shouldClose(open, isPending)) closeConfirm();
      }}
    >
      {view === null ? null : (
        <AlertDialogContent initialFocus={cancelRef}>
          <AlertDialogHeader>
            <AlertDialogTitle>{view.title}</AlertDialogTitle>
            <AlertDialogDescription>{view.description}</AlertDialogDescription>
          </AlertDialogHeader>
          <FormError message={error} />
          <AlertDialogFooter>
            <AlertDialogCancel ref={cancelRef} disabled={isPending}>
              取消
            </AlertDialogCancel>
            <AlertDialogAction
              variant={view.actionVariant}
              disabled={isPending}
              focusableWhenDisabled
              aria-labelledby={labelId}
              onClick={() => confirm()}
            >
              <span id={labelId}>{view.actionLabel}</span>
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      )}
    </AlertDialog>
  );
}

export type { ConfirmActionCopy, ConfirmActionDialogMotion, ConfirmActions };
export { ConfirmActionDialog };

/** 一种确认动作的文案。`copy` 字典按动作种类各给一份。 */
export type ConfirmActionCopy = {
  /** 动词，如「删除」。用在标题和确认按钮上。 */
  action: string;
  /** 处理中的确认按钮文案，「动词 + 中…」，如「删除中…」。 */
  pendingAction: string;
  /** 后果说明，如「此操作不可撤销。」 */
  description: string;
  /** 为真时确认按钮用 `destructive` 变体。 */
  destructive?: boolean;
};

/** 对话框正在显示的对象。关闭后保留，供关闭动画期间显示。 */
export type ShownConfirm<Kind extends string> = { kind: Kind; target: string };

export type ConfirmView = {
  title: string;
  description: string;
  actionLabel: string;
  actionVariant: "default" | "destructive";
};

/** 由文案、对象名与处理中状态得出对话框上的文字与确认按钮变体。 */
export function confirmView(
  copy: ConfirmActionCopy,
  target: string,
  isPending: boolean,
): ConfirmView {
  return {
    title: `${copy.action}「${target}」？`,
    description: copy.description,
    actionLabel: isPending ? copy.pendingAction : copy.action,
    actionVariant: copy.destructive ? "destructive" : "default",
  };
}

/**
 * 打开时跟随当前的 `kind` 与 `target`；关闭（`kind` 为 null）时保留上一次的内容。
 * 内容不变时返回 `prev` 本身，调用方可以用 `!==` 判断要不要更新。
 */
export function nextShown<Kind extends string>(
  prev: ShownConfirm<Kind> | null,
  kind: Kind | null,
  target: string,
): ShownConfirm<Kind> | null {
  if (kind === null) return prev;
  if (prev !== null && prev.kind === kind && prev.target === target) return prev;
  return { kind, target };
}

/** 对话框请求关闭（Esc、点遮罩、取消）时是否真的关闭：处理中一律不关。 */
export function shouldClose(open: boolean, isPending: boolean): boolean {
  return !open && !isPending;
}
